INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q1281436', 'Battle of Mardia', 'The Battle of Mardia, also known as Battle of Campus Mardiensis or Battle of Campus Ardiensis, was fought in late 316/early 317 between the forces of Roman Emperors Constantine I and Licinius. Its location was probably modern Harmanli (Bulgaria) in Thrace.', 316, NULL, NULL, NULL, NULL, NULL, 'year', '316', 55, 'https://en.wikipedia.org/wiki/Battle_of_Mardia'),
  ('Q9173231', 'Battle of Marcianople', 'The Battle of Marcianople or Marcianopolis took place in 376 following the Goths'' migration over the Danube. It was the first notable battle of the Gothic War of 376–382.', 376, NULL, NULL, NULL, NULL, NULL, 'year', '376', 48, 'https://en.wikipedia.org/wiki/Battle_of_Marcianople'),
  ('Q892169', 'Battle of the Utus', 'The Battle of the Utus was fought in 447 between the army of the Eastern Roman Empire, and the Huns led by Attila at Utus, a river that is today the Vit in Bulgaria. It was the last of the bloody pitched battles between the Eastern Roman Empire and the Huns, as the former attempted to stave off the Hunnic invasion.', 477, NULL, NULL, NULL, NULL, NULL, 'year', '477', 53, 'https://en.wikipedia.org/wiki/Battle_of_the_Utus'),
  ('Q602880', 'Battle of Anchialus', 'The Battle of Anchialus (Bulgarian: Битката при Анхиало) (Medieval Greek: Μάχη του Αγχίαλου) occurred in 708 near the modern-day town of Pomorie, Bulgaria', 708, NULL, NULL, NULL, NULL, NULL, 'year', '708', 60, 'https://en.wikipedia.org/wiki/Battle_of_Anchialus_(708)'),
  ('Q3621804', 'Battle of Marcellae', 'The Battle of Marcellae (Bulgarian: Битката при Маркели, Greek: Μάχη των Μαρκελλών) took place in 756 between the armies of the First Bulgarian Empire and the Byzantine Empire at Markeli, near the town of Karnobat in south eastern Bulgaria. The result was a Byzantine victory.', 756, NULL, NULL, NULL, NULL, NULL, 'year', '756', 51, 'https://en.wikipedia.org/wiki/Battle_of_Marcellae_(756)'),
  ('Q966312', 'Battle of Anchialus', 'The battle of Anchialus (Bulgarian: Битката при Анхиало) occurred in 763, near the town of Pomorie on the Bulgarian Black Sea Coast. The result was a Byzantine victory.', 763, 6, 30, NULL, NULL, NULL, 'day', '30 June 763', 52, 'https://en.wikipedia.org/wiki/Battle_of_Anchialus_(763)'),
  ('Q1578852', 'Battle of Marcellae', 'The Battle of Marcellae (Bulgarian: Битката при Маркели; Greek: Μάχη των Μαρκελλών) was fought on the 20 July 792 between the forces of the Byzantine Empire, led by Constantine VI, and those of the First Bulgarian Empire under Kardam. The Byzantines were routed and forced to retreat to Constantinople.', 792, NULL, NULL, NULL, NULL, NULL, 'year', '792', 50, 'https://en.wikipedia.org/wiki/Battle_of_Marcellae'),
  ('Q1578840', 'Siege of Serdica (809)', 'The siege of Serdica (Bulgarian: Обсадата на Сердика) took place in the spring of 809 at modern Sofia, Bulgaria. As a result, the city was annexed to the Bulgarian State and remained so until the fall of the First Bulgarian Empire.', 809, NULL, NULL, NULL, NULL, NULL, 'year', '809', 45, 'https://en.wikipedia.org/wiki/Siege_of_Serdica_(809)'),
  ('Q403416', 'Battle of Pliska', 'The Battle of Pliska or Battle of Vărbitsa Pass was a series of battles between the forces of the Byzantine Empire under Emperor Nicephorus I, and the First Bulgarian Empire under Khan Krum in July 811. The Byzantines plundered and burned the Bulgar capital Pliska which gave time for the Bulgarians to block passes in the Balkan Mountains that served as exits out of Bulgaria.', 811, 7, 26, NULL, NULL, NULL, 'day', '26 July 811', 65, 'https://en.wikipedia.org/wiki/Battle_of_Pliska'),
  ('Q1048401', 'Battle of Versinikia', 'Bulgarian Battle of Versinikia (Bulgarian: Битката при Версиникия; Greek: Μάχη της Βερσινικίας) was a battle fought in 813 AD between the Byzantine Empire and the Bulgarian Empire, near the city of Adrianople (Edirne), in modern-day Turkey. The Bulgarian army, led by Krum of Bulgaria, defeated the Byzantine forces.', 813, 6, 22, NULL, NULL, NULL, 'day', '22 June 813', 57, 'https://en.wikipedia.org/wiki/Battle_of_Versinikia'),
  ('Q658731', 'Battle of Achelous', 'The Battle of Achelous or Acheloos (Bulgarian: Битката при Ахелой, Greek: Μάχη του Αχελώου), also known as the Battle of Anchialus, took place on 20 August 917, on the Achelous river near the Bulgarian Black Sea coast, close to the fortress Tuthom (modern Pomorie) between Bulgarian and Byzantine forces. The Bulgarians obtained a decisive victory which not only secured the previous successes of Simeon I, but made him de facto ruler of the whole Balkan Peninsula, excluding the well-protected Byzantine capital Constantinople and the Peloponnese.', 917, 8, 20, NULL, NULL, NULL, 'day', '20 August 917', 61, 'https://en.wikipedia.org/wiki/Battle_of_Achelous_(917)'),
  ('Q737655', 'Siege of Dorostolon', 'The Siege and Battle of Dorostolon (Silistra) was fought in 971 between the Byzantine Empire and forces of Kievan Rus''. The Byzantines, led by John I Tzimiskes, were victorious.', 971, NULL, NULL, 971, 7, 24, 'year', '971', 57, 'https://en.wikipedia.org/wiki/Siege_of_Dorostolon'),
  ('Q2292026', 'Battle of the Gates of Trajan', 'The Battle of the Gates of Trajan (Bulgarian: Битка край Траянови врати, Medieval Greek: Μάχη στις Πύλες του Τραϊανού) was a battle between Byzantine and Bulgarian forces in the year 986. It took place in the pass of the same name, modern Trayanovi Vrata, in Sofia Province, Bulgaria.', 986, 8, 17, NULL, NULL, NULL, 'day', '17 August 986', 58, 'https://en.wikipedia.org/wiki/Battle_of_the_Gates_of_Trajan'),
  ('Q153702', 'Battle of Beroia', 'The Battle of Beroia (modern Stara Zagora) was fought in 1122 between the Pechenegs and the Byzantine Empire under Emperor John II Komnenos (r. 1118–1143) in what is now Bulgaria.', 1122, NULL, NULL, NULL, NULL, NULL, 'year', '1122', 57, 'https://en.wikipedia.org/wiki/Battle_of_Beroia'),
  ('Q1459494', 'Battle of Klokotnitsa', 'The Battle of Klokotnitsa (Bulgarian: Битката при Клокотница, Bitkata pri Klokotnitsa) occurred on 9 March 1230 near the village of Klokotnitsa (today in Haskovo Province, Bulgaria) between the Second Bulgarian Empire and the Empire of Thessalonica. As a result, Bulgaria emerged once again as the most powerful state in South-Eastern Europe.', 1230, 3, 9, NULL, NULL, NULL, 'day', '9 March 1230', 58, 'https://en.wikipedia.org/wiki/Battle_of_Klokotnitsa'),
  ('Q2094999', 'Battle of Skafida', 'The Battle of Skafida (Bulgarian: Битка при Скафида) was an engagement between the Bulgarian Empire and the Byzantine Empire which occurred in 1304 near Poros (Burgas), modern Bulgaria. The outcome was Bulgarian victory.', 1304, NULL, NULL, NULL, NULL, NULL, 'year', '1304', 50, 'https://en.wikipedia.org/wiki/Battle_of_Skafida'),
  ('Q1400440', 'Battle of Velbazhd', 'The Battle of Velbazhd (Bulgarian: битка при Велбъжд, romanized: bitka pri Velbazhd; Serbian: Битка код Велбужда, romanized: Bitka kod Velbužda) was fought by the Second Bulgarian Empire and the Kingdom of Serbia on 28 July 1330, near the town of Velbazhd (present day Kyustendil). The growing power of the Serbian Kingdom from the late 13th century raised serious concerns in the traditional Balkan powers Bulgaria and Byzantine Empire which agreed for joint military actions against Serbia in 1327.', 1330, 7, 28, NULL, NULL, NULL, 'day', '28 July 1330', 58, 'https://en.wikipedia.org/wiki/Battle_of_Velbazhd'),
  ('Q1889668', 'Battle of Rusokastro', 'The Battle of Rusokastro (Bulgarian: Битка при Русокастро, Greek: Μάχη τοῦ Ῥουσοκάστρου) occurred on 18 July 1332 near the village of Rusokastro, Bulgaria, between the armies of the Bulgarian and Byzantine Empires.', 1332, 7, 18, NULL, NULL, NULL, 'day', '18 July 1332', 51, 'https://en.wikipedia.org/wiki/Battle_of_Rusokastro'),
  ('Q283984', 'Battle of Ihtiman', 'The Battle of Ihtiman occurred in 1355 between Bulgarians and Ottomans and resulted in a Bulgarian pyrrhic victory. The exact location is not known, but in an anonymous Bulgarian chronicle, it is mentioned that the armies of Michail Asen engaged the invading forces before they could reach Sofia.', 1355, NULL, NULL, NULL, NULL, NULL, 'year', '1355', 45, 'https://en.wikipedia.org/wiki/Battle_of_Ihtiman'),
  ('Q3394064', 'Siege of Tarnovo', 'The siege of Tarnovgrad occurred in the spring of 1393 and resulted in a decisive Ottoman victory. With the fall of its capital, the Bulgarian Empire was reduced to a few fortresses along the Danube.', 1393, 7, 17, 1393, 7, 17, 'day', '17 July 1393', 51, 'https://en.wikipedia.org/wiki/Siege_of_Tarnovo'),
  ('Q212220', 'Battle of Nicopolis', 'The Battle of Nicopolis took place on 25 September 1396 and resulted in the rout of an allied Crusader army, assisted by the Venetian navy, at the hands of an Ottoman force, raising the siege of the Danubian fortress of Nicopolis and leading to the end of the Second Bulgarian Empire. It is often referred to as the Crusade of Nicopolis, as it was one of the last major Crusades of the Middle Ages, together with the Crusade of Varna in 1443–1444.', 1396, 9, 25, NULL, NULL, NULL, 'day', '25 September 1396', 73, 'https://en.wikipedia.org/wiki/Battle_of_Nicopolis'),
  ('Q4817327', 'Battle of Çamurlu', 'The Battle of Çamurlu was fought on 5 July 1413 between Musa Çelebi and Mehmed Çelebi, both sons of Bayezid I, as the last conflict of the Ottoman civil war known as the Ottoman Interregnum. The battle decided which son of Bayezid I would finally reunite the Ottoman Empire, with Mehmed Çelebi becoming Mehmed I of the Ottoman Empire.', 1413, 7, 5, NULL, NULL, NULL, 'day', '5 July 1413', 47, 'https://en.wikipedia.org/wiki/Battle_of_%C3%87amurlu'),
  ('Q18639123', 'Battle of Zlatica', 'The Battle of Zlatitsa was fought on 12 December 1443 between the Ottoman Empire and Serbian and Hungarian troops in the Balkans as part of the larger Crusade of Varna. The battle was fought at Zlatitsa Pass (Bulgarian: Златишки проход) (Turkish: İzladi Derbendi) near the town of Zlatitsa in the Balkan Mountains, Ottoman Empire (modern-day Bulgaria).', 1443, 12, 12, NULL, NULL, NULL, 'day', '12 December 1443', 45, 'https://en.wikipedia.org/wiki/Battle_of_Zlatitsa'),
  ('Q32832', 'Battle of Varna', 'The Battle of Varna took place on 10 November 1444 near Varna in what is today eastern Bulgaria. The Ottoman army under Sultan Murad II (who did not actually rule the sultanate at the time) defeated the Crusaders commanded by King Władysław III of Poland and Hungary, John Hunyadi (acting as commander of the combined Christian forces) and Mircea II of Wallachia.', 1444, 11, 10, NULL, NULL, NULL, 'day', '10 November 1444', 73, 'https://en.wikipedia.org/wiki/Battle_of_Varna'),
  ('Q123227', 'Treaty of Küçük Kaynarca', 'The Treaty of Küçük Kaynarca (Turkish: Küçük Kaynarca Antlaşması; Russian: Кючук-Кайнарджийский мир), formerly often written Kuchuk-Kainarji, was a peace treaty signed on 21 July [O.S. 10 July] 1774, in Küçük Kaynarca (today Kaynardzha, Bulgaria) between the Russian Empire and the Ottoman Empire, ending the Russo-Turkish War of 1768–1774 with major concessions to Russia. The concessions to Russia were not merely territorial; not only was the Crimean Khanate (not Crimea proper) effectively ceded to Russia, but Russia also gained the right to construct a Russian Orthodox church in…', 1774, 7, 21, NULL, NULL, NULL, 'day', '21 July 1774', 73, 'https://en.wikipedia.org/wiki/Treaty_of_K%C3%BC%C3%A7%C3%BCk_Kaynarca'),
  ('Q1985387', 'Battle of Kozludzha', 'The Battle of Kozludzha (also known as the Battle of Kozludža or the Battle of Kozluca), fought on 20 June (Old Style — June 9) 1774 near the village of Kozludzha (now Suvorovo, Bulgaria), was one of the final and decisive battles of the Russo-Turkish War (1768–1774). The Russians managed to rout the Ottoman army, scoring a major victory.', 1774, 6, 9, NULL, NULL, NULL, 'day', '9 June 1774', 45, 'https://en.wikipedia.org/wiki/Battle_of_Kozludzha'),
  ('Q648223', 'Battle of Cape Kaliakra', 'The Battle of Cape Kaliakra (Kaliakria, Caliacria; Russian: Калиакрийское сражение) was the last naval battle of the Russo-Turkish War (1787–1792). It took place on 11 August 1791 off the coast of Cape Kaliakra, Bulgaria, in the Black Sea.', 1791, 8, 11, NULL, NULL, NULL, 'day', '11 August 1791', 47, 'https://en.wikipedia.org/wiki/Battle_of_Cape_Kaliakra'),
  ('Q2032250', 'Battle of Kulevicha', 'The Battle of Kulevicha, also known as the Battle of Kulevcha or Kulewtscha, was fought during the Russo-Turkish War, 1828–1829, on 11 June 1829, between Russia and the Ottoman Empire. It ended with a Russian victory achieved by Commander Hans von Diebitsch (Ivan Dibich-Zabalkansky).', 1829, 6, 11, NULL, NULL, NULL, 'day', '11 June 1829', 47, 'https://en.wikipedia.org/wiki/Battle_of_Kulevicha'),
  ('Q815207', 'Siege of Silistra (1854)', 'The siege of Silistria, or siege of Silistra, was a key engagement in the Crimean War, fought from 11 May to 23 June 1854 between the Russian Empire and the Ottoman Empire in present-day Bulgaria. The Russian army, numbering up to 90,000 men with 266 guns, attempted to capture the Danubian fortress of Silistria as part of a broader strategy to outflank Ottoman defences and pre-empt an expected Allied landing at Varna.', 1854, NULL, NULL, 1854, 6, 24, 'year', '1854', 50, 'https://en.wikipedia.org/wiki/Siege_of_Silistria_(1854)'),
  ('Q3043924', 'Kresna-Razlog uprising', 'The Kresna–Razlog uprising (Bulgarian: Кресненско-Разложко въстание, romanized: Kresnensko-Razlozhko vastanie), also known as the Kresna uprising (Macedonian: Кресненско востание, romanized: Kresnensko vostanie), was an anti-Ottoman Bulgarian uprising that took place in Ottoman Macedonia, predominantly in the areas of modern Blagoevgrad Province in Bulgaria in late 1878 and early 1879. It was named by the insurgents as the Macedonian uprising.', 1870, NULL, NULL, NULL, NULL, NULL, 'decade', '1870s', 50, 'https://en.wikipedia.org/wiki/Kresna%E2%80%93Razlog_uprising'),
  ('Q622059', 'April Uprising of 1876', 'The April Uprising (Bulgarian: Априлско въстание, romanized: Aprilsko vastanie) was an insurrection organised by the Bulgarians in the Ottoman Empire from April to May 1876. The rebellion was suppressed by irregular Ottoman bashi-bazouk units that engaged in indiscriminate slaughter of both rebels and non-combatants (see Batak massacre).', 1876, NULL, NULL, NULL, NULL, NULL, 'year', '1876', 65, 'https://en.wikipedia.org/wiki/April_Uprising_of_1876'),
  ('Q116004', 'Battle of Shipka Pass', 'The Battle of Shipka Pass consisted of four battles that were fought between the Russian Empire, aided by Bulgarian volunteers known as opalchentsi, and the Ottoman Empire for control over the vital Shipka Pass during the Russo-Turkish War (1877–1878). The final battle is known as the battle of Shipka-Sheynovo or simply the battle of Sheynovo (Russian: Шипко-Шейновское сражение; Bulgarian: Шейновска битка).', 1877, 7, 17, 1878, 1, 9, 'day', '17 July 1877 – 9 January 1878', 57, 'https://en.wikipedia.org/wiki/Battle_of_Shipka_Pass'),
  ('Q780367', 'Siege of Plevna', 'The siege of Plevna or Pleven, was a major battle of the Russo-Turkish War of 1877–1878, fought by the joint army of the Russian Empire and the Kingdom of Romania against the Ottoman Empire. After the Russian army crossed the Danube at Svishtov, it began advancing towards the centre of modern Bulgaria, with the aim of crossing the Balkan Mountains to Constantinople, avoiding the fortified Turkish fortresses on the Black Sea coast.', 1877, 7, 20, 1877, 12, 10, 'day', '20 July 1877 – 10 December 1877', 58, 'https://en.wikipedia.org/wiki/Siege_of_Plevna'),
  ('Q2667561', 'Battle of Nikopol', 'The Battle of Nikopol, or Nicopolis (Turkish: Niğbolu Muharebesi), was one of the early battles of the Russo-Turkish War (1877–1878). As the Russian army crossed the Danube river, they approached the fortified city of Nikopol (Nicopolis).', 1877, 7, 16, NULL, NULL, NULL, 'day', '16 July 1877', 52, 'https://en.wikipedia.org/wiki/Battle_of_Nikopol'),
  ('Q2976481', 'Battle of Gorni Dubnik', 'The Battle of Gorni Dubnik took place during the Russo-Turkish War on 24 October 1877. In an effort to reduce the fortress of Pleven quicker, Russian forces began targeting garrisons along the Ottoman supply and communications route.', 1877, 10, 24, NULL, NULL, NULL, 'day', '24 October 1877', 48, 'https://en.wikipedia.org/wiki/Battle_of_Gorni_Dubnik'),
  ('Q771423', 'Battle of Philippopolis', 'The Battle of Plovdiv, or Battle of Philippopolis, was one of the final battles of the 1877–1878 Russo-Turkish War. Following the crushing Russian victory at the last battle of Shipka Pass, Russian commander Gen.', 1878, 1, 17, NULL, NULL, NULL, 'day', '17 January 1878', 45, 'https://en.wikipedia.org/wiki/Battle_of_Plovdiv_(1878)'),
  ('Q1861319', 'Battle of Slivnitsa', 'The Battle of Slivnitsa (Bulgarian: Битка при Сливница, Serbian: Битка на Сливници) was a battle between the Bulgarian Army and the Royal Serbian Army from 17 to 19 November 1885, in the Serbo-Bulgarian War. The Bulgarian victory solidified the unification between the Principality of Bulgaria and Eastern Rumelia.', 1885, 11, 17, 1885, 11, 19, 'day', '17 November 1885 – 19 November 1885', 47, 'https://en.wikipedia.org/wiki/Battle_of_Slivnitsa'),
  ('Q1300440', 'Treaty of Bucharest', 'The Treaty of Bucharest was signed by Serbia and Bulgaria on 3 March [O.S. 19 February] 1886 in Bucharest, the capital of Romania, and marked the end of the Serbo-Bulgarian War. The treaty contained a single article, stating that peace between the two countries was restored.', 1886, 3, 3, NULL, NULL, NULL, 'day', '3 March 1886', 57, 'https://en.wikipedia.org/wiki/Treaty_of_Bucharest_(1886)'),
  ('Q1628090', 'Bulgarian Declaration of Independence', 'The de jure independence of Bulgaria (Bulgarian: Независимост на България, romanized: Nezavisimost na Bǎlgariya) from the Ottoman Empire was proclaimed on 5 October [O.S. 22 September] 1908 in the old capital of Tarnovo by Prince Ferdinand of Bulgaria, who afterwards took the title "Tsar".', 1908, 9, 22, NULL, NULL, NULL, 'day', '22 September 1908', 56, 'https://en.wikipedia.org/wiki/Bulgarian_Declaration_of_Independence'),
  ('Q959066', 'Battle of Kaliakra', 'The Battle of Kaliakra, usually known as the Attack of the Drazki (Bulgarian: Атаката на Дръзки) in Bulgaria, was a maritime action between four Bulgarian torpedo boats and the Ottoman cruiser Hamidiye in the Black Sea. It took place on 21 November 1912 at 32 miles off Bulgaria''s primary port of Varna.', 1912, 11, 21, NULL, NULL, NULL, 'day', '21 November 1912', 47, 'https://en.wikipedia.org/wiki/Battle_of_Kaliakra_(1912)'),
  ('Q4871390', 'Battle of Kardzhali', 'The Battle of Kircaali or Battle of Kardzhali was part of the First Balkan War between the armies of Bulgaria and the Ottoman Empire. It took place on 21 October 1912, when the Bulgarian Haskovo Detachment defeated the Ottoman Kırcaali Detachment of Yaver Pasha and permanently joined Kardzhali and the Eastern Rhodopes to Bulgaria.', 1912, 10, 21, NULL, NULL, NULL, 'day', '21 October 1912', 47, 'https://en.wikipedia.org/wiki/Battle_of_Kardzhali'),
  ('Q2888998', 'Battle of Kresna Gorge', 'The Battle of Kresna Gorge was fought in 1913 between the Greeks and the Bulgarians during the Second Balkan War. The battle was fought over an eleven-day period, between 8–18 July, over a front of 20 km, in a maze of forests and mountains.', 1913, 7, 21, 1913, 7, 31, 'day', '21 July 1913 – 31 July 1913', 47, 'https://en.wikipedia.org/wiki/Battle_of_Kresna_Gorge'),
  ('Q16824920', 'Bulgarian–Ottoman alliance', 'An Ottoman–Bulgarian (or Turco-Bulgarian) alliance was signed in Sofia on 19 August (6 August O.S.) 1914 during the opening month of the First World War, although at the time both the signatories were neutral. The Minister of the Interior, Talaat Pasha, and President Halil Bey of the Chamber of Deputies signed the treaty on behalf of the Ottoman Empire (Turkey) and Prime Minister Vasil Radoslavov on behalf of the Kingdom of Bulgaria.', 1914, 8, 19, NULL, NULL, NULL, 'day', '19 August 1914', 45, 'https://en.wikipedia.org/wiki/Ottoman%E2%80%93Bulgarian_alliance'),
  ('Q956737', 'Battle of Turtucaia', 'The Battle of Turtucaia (Romanian: Bătălia de la Turtucaia; Bulgarian: Битка при Тутракан, Bitka pri Tutrakan), also known as Tutrakan Epopee (Bulgarian: Тутраканска епопея, Tutrakanska epopeya) in Bulgaria, was the opening battle of the first Central Powers offensive during the Romanian Campaign of World War I. The battle lasted for five days and ended with the capture of the fortress of Turtucaia (now Tutrakan) and the surrender of its Romanian defenders.', 1916, 9, 2, 1916, 9, 6, 'day', '2 September 1916 – 6 September 1916', 55, 'https://en.wikipedia.org/wiki/Battle_of_Turtucaia'),
  ('Q2448616', 'Battle of Dobrich', 'The Battle of Bazargic, also known as the Battle of Dobrich or the Dobrich epopee (Bulgarian: Добричка епопея), (Russian: Битва при Добриче), took place between 5 and 7 September 1916 between a joint Bulgarian–German–Ottoman force, consisting mainly of the Bulgarian Third Army, and a Romanian–Russian force, including a Division of Serbian Volunteers serving under the Russian 47th Corps. The battle was part of the Romanian campaign towards the end of 1916.', 1916, 9, 5, 1916, 9, 7, 'day', '5 September 1916 – 7 September 1916', 47, 'https://en.wikipedia.org/wiki/Battle_of_Bazargic'),
  ('Q2632694', 'Flămânda Offensive', 'The Flămânda Offensive (or Flămânda Maneuver), which took place during World War I between 29 September and 5 October 1916, was an offensive across the Danube mounted by the Romanian 3rd Army supported by Romanian coastal artillery. Named after the hamlet of Flămânda, the battle represented a consistent effort by the Romanian Army to stop the Central Powers'' southern offensive led by August von Mackensen.', 1916, 9, 29, 1916, 10, 5, 'day', '29 September 1916 – 5 October 1916', 48, 'https://en.wikipedia.org/wiki/Fl%C4%83m%C3%A2nda_Offensive'),
  ('Q12295718', 'Struma operation', 'The Struma operation was the occupation of a part of northeastern mainland Greece by the Bulgarian army during the First World War between 17–23 August 1916. It was named after the Struma (Strymonas) river.', 1916, 8, 17, 1916, 8, 23, 'day', '17 August 1916 – 23 August 1916', 45, 'https://en.wikipedia.org/wiki/Struma_operation'),
  ('Q920202', 'Battle of Doiran', 'The Third Battle of Doiran was fought from 18 to 19 September 1918, with the British and the Greeks assaulting the positions of the Bulgarian First Army near Doiran Lake. The battle was part of World War I and took place in the Balkan Theatre.', 1918, 9, 18, 1918, 9, 19, 'day', '18 September 1918 – 19 September 1918', 55, 'https://en.wikipedia.org/wiki/Battle_of_Doiran_(1918)'),
  ('Q960894', '1923 Bulgarian coup d''état', 'The 1923 Bulgarian coup d''état, also known as the 9 June coup d''état (Bulgarian: Деветоюнски преврат, Devetoyunski prevrat), was a coup d''état in Bulgaria implemented by armed forces under General Ivan Valkov''s Military League on the evening of 9 June 1923. Hestitantly legitimized by a decree of Tsar Boris III of Bulgaria, the coup overthrew the elected government headed by Aleksandar Stamboliyski of the Bulgarian Agrarian National Union (BANU), and replaced it with one under Aleksandar Tsankov.', 1923, 6, 9, NULL, NULL, NULL, 'day', '9 June 1923', 52, 'https://en.wikipedia.org/wiki/1923_Bulgarian_coup_d''%C3%A9tat'),
  ('Q891868', 'St Nedelya Church assault', 'The St Nedelya Church bombing was a terrorist attack on St Nedelya Church in Sofia, Bulgaria. It was carried out on 16 April 1925, when a group of the Military Organisation of the Bulgarian Communist Party directed and supplied by the Soviet Military Intelligence blew up the church''s roof during the funeral service of General Konstantin Georgiev, who had been killed in a previous communist assault on 14 April.', 1925, 4, 16, NULL, NULL, NULL, 'day', '16 April 1925', 61, 'https://en.wikipedia.org/wiki/St._Nedelya_Church_bombing'),
  ('Q4996248', '1934 Bulgarian coup d''état', 'The Bulgarian coup d''état of 1934, also known as the 19 May coup d''état (Bulgarian: Деветнадесетомайски преврат, Devetnadesetomayski prevrat), was a coup d''état in the Kingdom of Bulgaria carried out by the Zveno military organization and the Military Union with the aid of the Bulgarian Army. It overthrew the government of the wide People''s Bloc coalition and replaced it with one under Kimon Georgiev.', 1934, 5, 19, NULL, NULL, NULL, 'day', '19 May 1934', 47, 'https://en.wikipedia.org/wiki/1934_Bulgarian_coup_d''%C3%A9tat'),
  ('Q618048', '1944 Bulgarian coup d''état', 'The 1944 Bulgarian coup d''état, also known as the 9 September coup d''état (Bulgarian: Деветосептемврийски преврат, romanized: Devetoseptemvriyski prevrat), was a coup that overthrew the government of Kingdom of Bulgaria on the eve of 9 September 1944. During the Communist era, official propaganda called the coup the People''s Uprising of 9 September on the grounds of the broad unrest and the Socialist Revolution as it was a turning point politically and the beginning of radical reforms towards Soviet-style socialism.', 1944, 9, 9, NULL, NULL, NULL, 'day', '9 September 1944', 60, 'https://en.wikipedia.org/wiki/1944_Bulgarian_coup_d''%C3%A9tat'),
  ('Q4578073', '1978 Balkan Bulgarian Tupolev Tu-134 crash', 'Balkan Bulgarian Airlines Flight 107 was an accident that occurred on 16 March 1978, when a Tupolev Tu-134 operated by Balkan Bulgarian Airlines crashed on an international flight from Sofia Airport to Warsaw Airport. All 73 passengers and crew died in the crash (66 passengers and a crew of 7).', 1978, 3, 16, NULL, NULL, NULL, 'day', '16 March 1978', 47, 'https://en.wikipedia.org/wiki/Balkan_Bulgarian_Airlines_Flight_107'),
  ('Q421463', 'Bulgarian nuclear power referendum', 'A referendum on building a new nuclear power plant was held in Bulgaria on 27 January 2013. Whilst it was not explicitly mentioned in the question, it was widely acknowledged that the referendum was about restarting construction at the Belene Nuclear Power Plant.', 2013, 1, 27, NULL, NULL, NULL, 'day', '27 January 2013', 45, 'https://en.wikipedia.org/wiki/2013_Bulgarian_nuclear_power_referendum'),
  ('Q16879871', '2014 Southeast Europe floods', 'Between 13 and 18 May 2014 a low-pressure cyclone designated Tamara and Yvette affected a large area of Southeastern and Central Europe, causing floods and landslides. Serbia and Bosnia and Herzegovina suffered the greatest damage, as the rain was the heaviest in 120 years of recorded weather measurements.', 2014, 5, 27, 2014, 5, 27, 'day', '27 May 2014', 63, 'https://en.wikipedia.org/wiki/2014_Southeast_Europe_floods'),
  ('Q81068910', 'COVID-19 pandemic', 'The global COVID-19 pandemic (also known as the coronavirus pandemic), caused by severe acute respiratory syndrome coronavirus 2 (SARS-CoV-2), began with an outbreak in Wuhan, China, in December 2019. It spread to other parts of Asia and then worldwide in early 2020.', 2019, 12, 1, NULL, NULL, NULL, 'day', '1 December 2019', 100, 'https://en.wikipedia.org/wiki/COVID-19_pandemic'),
  ('Q86458103', 'COVID-19 pandemic in Europe', 'The global COVID-19 pandemic arrived in Europe with its first confirmed case in Bordeaux, France, on 24 January 2020, and subsequently spread widely across the continent. By 17 March 2020, every country in Europe had confirmed a case, and all have reported at least one death, with the exception of Vatican City.', 2020, 1, 24, NULL, NULL, NULL, 'day', '24 January 2020', 65, 'https://en.wikipedia.org/wiki/COVID-19_pandemic_in_Europe'),
  ('Q97208898', '2020–2021 Bulgarian protests', 'A series of protests were held from 2020 to 2021 in Bulgaria, mainly in the capital Sofia, as well as cities with a large Bulgarian diaspora, such as Brussels, Paris, Madrid, Barcelona, Berlin and London. The protests, sometimes called "Revolution of Dignity", were the culmination of long-standing grievances against endemic corruption and state capture, particularly associated with prime minister Boyko Borisov''s governments, in power since 2009.', 2020, 7, 9, 2021, 4, 16, 'day', '9 July 2020 – 16 April 2021', 47, 'https://en.wikipedia.org/wiki/2020%E2%80%932021_Bulgarian_protests'),
  ('Q122311648', 'Storm Daniel', 'Storm Daniel, also known as Medicane Daniel or Cyclone Daniel, was a relatively weak yet catastrophic and erratic tropical cyclone that became the deadliest Mediterranean tropical-like cyclone in recorded history, as well as the second-costliest tropical cyclone on record outside of the North Atlantic Basin (after Typhoon Doksuri). Forming as a low-pressure system around 4 September 2023, the storm affected Greece, Bulgaria, and Turkey with extensive flooding.', 2023, 9, NULL, 2023, 9, 13, 'month', 'September 2023 – 13 September 2023', 72, 'https://en.wikipedia.org/wiki/Storm_Daniel'),
  ('Q137366682', '2025 Bulgarian protests', 'Protests began in Bulgaria on 26 November 2025 after the Zhelyazkov government announced a 2026 budget plan that would have increased taxes—specifically, the amounts individuals were to contribute to pension and social-security programs. The government suspended, then withdrew the budget, but demonstrations continued, with protestors demanding the resignation of the government and new elections.', 2025, 11, 26, NULL, NULL, NULL, 'day', '26 November 2025', 48, 'https://en.wikipedia.org/wiki/2025%E2%80%932026_Bulgarian_protests');
